# AIM ---------------------------------------------------------------------
# read in the salmon quantification, build the table of raw counts and compare it with the one generated by nextflow.
# run from the project root (analysis_R45_pixi), paths are relative to it.

# libraries ---------------------------------------------------------------
library("tidyverse")
library("DESeq2")
library("tximport")

# annotation from GTF -----------------------------------------------------
# the GTF is the NCBI/RefSeq-like one (gene_id is already the gene symbol, only exon/CDS features, no biotype)
gtf_file <- "../../data/genes.filtered.gtf"

gtf <- rtracklayer::import(gtf_file) %>%
  as.data.frame()

# transcript to gene map
tx2gene <- gtf %>%
  dplyr::filter(type == "exon") %>%
  dplyr::select(TXNAME = transcript_id, GENEID = gene_id, SYMBOL = gene_name) %>%
  distinct()

head(tx2gene)
dim(tx2gene)

# a transcript should map to a single gene
tx2gene %>%
  dplyr::count(TXNAME) %>%
  dplyr::filter(n > 1)

saveRDS(tx2gene, "../../out/object/annotation_GTF.rds")

# read in the expression data ---------------------------------------------
# list all the quantified samples (one folder per sample)
samples <- list.dirs(path = "../../data/salmon_quant", full.names = T, recursive = F)
files <- file.path(samples, "quant.sf")
names(files) <- basename(samples)

# keep only the samples present in the samplesheet
samplesheet <- read_csv("../../data/samplesheet.csv")
setdiff(names(files), samplesheet$sample_id)
setdiff(samplesheet$sample_id, names(files)) # samples without quantification
files <- files[names(files) %in% samplesheet$sample_id]

txi <- tximport(files, type = "salmon", tx2gene = tx2gene[, c("TXNAME", "GENEID")], countsFromAbundance = "lengthScaledTPM")
str(txi)

saveRDS(txi, "../../out/object/txi_GTF.rds")

# round the counts to be imported into DESeq2
data <- txi$counts %>%
  round()

saveRDS(data, "../../out/object/raw_count_salmon_GTF.rds")


# -------------------------------------------------------------------------
# compare the table of counts with the automatic object generated by nextflow
load("../../data/deseq2.dds.RData")
data_nextflow <- counts(dds)
dim(data_nextflow)
dim(data)

# fux the sample names of data_nextflow
colnames(data_nextflow) <- colnames(data_nextflow) %>% str_remove(pattern = "X")

common_samples <- intersect(colnames(data_nextflow), colnames(data))
common_genes <- intersect(rownames(data_nextflow), rownames(data))

# the two tables should be identical
all.equal(data_nextflow[common_genes, common_samples], data[common_genes, common_samples], check.attributes = F)

# confirm using the delta
df_test <- full_join(
  data_nextflow[common_genes, common_samples] %>% as.data.frame() %>% rownames_to_column("gene") %>% pivot_longer(names_to = "samples", values_to = "count", -gene),
  data[common_genes, common_samples] %>% as.data.frame() %>% rownames_to_column("gene") %>% pivot_longer(names_to = "samples", values_to = "count", -gene),
  by = c("gene", "samples"), suffix = c(".nextflow", ".GTF"))

df_test %>%
  dplyr::filter(!complete.cases(.))

df_test %>%
  mutate(delta = count.nextflow - count.GTF) %>%
  dplyr::filter(delta != 0)

# -------------------------------------------------------------------------
# compare the table of counts with the automatic summary table generated by nextflow
data_table_nextflow <- read_tsv("../../data/salmon.merged.gene_counts_length_scaled.tsv") %>%
  select(-gene_name) %>%
  column_to_rownames("gene_id") %>%
  round(digits = 0) %>%
  as.matrix()
dim(data_table_nextflow)
dim(data)

common_samples <- intersect(colnames(data_table_nextflow), colnames(data))
common_genes <- intersect(rownames(data_table_nextflow), rownames(data))

# the two tables should be identical
all.equal(data_table_nextflow[common_genes, common_samples], data[common_genes, common_samples], check.attributes = F)

# confirm using the delta
df_test <- full_join(
  data_table_nextflow[common_genes, common_samples] %>% as.data.frame() %>% rownames_to_column("gene") %>% pivot_longer(names_to = "samples", values_to = "count", -gene),
  data[common_genes, common_samples] %>% as.data.frame() %>% rownames_to_column("gene") %>% pivot_longer(names_to = "samples", values_to = "count", -gene),
  by = c("gene", "samples"), suffix = c(".nextflow", ".GTF"))

df_test %>%
  dplyr::filter(!complete.cases(.))

df_test %>%
  mutate(delta = count.nextflow - count.GTF) %>%
  dplyr::filter(delta != 0)
